use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\LiveDisplaySessionService;
Auth::requireAdmin();$test=!empty($projectionTest);$pdo=Database::connection();LiveDisplaySessionService::ensure($pdo);$eventTable=$test?'bdc_test_events':'bdc_events';$roundTable=$test?'bdc_test_scoring_rounds':'bdc_scoring_rounds';
$events=$pdo->query("SELECT DISTINCT e.id,e.name,e.event_date FROM {$eventTable} e JOIN {$roundTable} r ON r.event_id=e.id ORDER BY e.event_date DESC,e.name")->fetchAll();$rounds=$pdo->query("SELECT r.id,r.event_id,r.division,r.round_type,r.status FROM {$roundTable} r ORDER BY r.event_id,r.division,FIELD(r.round_type,'heats','semifinal','final'),r.id")->fetchAll();$saved=$pdo->prepare("SELECT s.id,s.group_name,COUNT(se.event_id) event_count FROM bdc_live_display_sessions s JOIN bdc_live_display_session_events se ON se.session_id=s.id WHERE s.data_mode=:m AND s.is_enabled=1 AND s.group_name IS NOT NULL GROUP BY s.id ORDER BY s.updated_at DESC");$saved->execute(['m'=>$test?'test':'real']);$saved=$saved->fetchAll();
$sessionId=(int)($_GET['festival_session']??0);$festival=$sessionId?LiveDisplaySessionService::byId($pdo,$sessionId,$test):null;$members=$festival?LiveDisplaySessionService::members($pdo,$sessionId,$test):[];$allowed=$festival?array_map(fn($r)=>(int)$r['id'],$members):array_map(fn($r)=>(int)$r['id'],$events);$notice=$_SESSION['festival_projection_notice']??'';$error=$_SESSION['festival_projection_error']??'';unset($_SESSION['festival_projection_notice'],$_SESSION['festival_projection_error']);$title=$test?'Test Live Screen Projector':'Live Screen Projector';$controlBase=url('admin/live-screen/control.php');
$festivalFinals=[];$playlistSelected=[];if($festival&&$allowed){$marks=implode(',',array_fill(0,count($allowed),'?'));$q=$pdo->prepare("SELECT r.id,r.event_id,r.division,r.status,e.name event_name FROM {$roundTable} r JOIN {$eventTable} e ON e.id=r.event_id WHERE r.event_id IN ({$marks}) AND r.round_type='final' ORDER BY e.event_date,e.name,r.division,r.id");$q->execute($allowed);$festivalFinals=$q->fetchAll();$q=$pdo->prepare('SELECT CONCAT(round_id,\':\',screen_type) value FROM bdc_live_display_playlist_items WHERE session_id=:s ORDER BY sort_order');$q->execute(['s'=>$sessionId]);$playlistSelected=$q->fetchAll(PDO::FETCH_COLUMN);}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title><?=e($title)?> | BDC</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f4f6f9}.workspace,.festival{border:0;border-radius:16px}.festival{border-left:5px solid <?= $test?'#ffc107':'#dc3545' ?>}.event-check{border:1px solid #dbe2ea;border-radius:12px;padding:10px;background:#fff}.festival-switcher{display:flex;gap:9px;overflow-x:auto;padding:3px 2px 9px;scrollbar-width:thin}.event-tab,.division-tab,.round-chip{border:1px solid #d7dee7;border-radius:11px;padding:10px 14px;background:#fff;font-weight:700;white-space:nowrap}.event-tab{min-width:210px;text-align:left}.event-tab small{display:block;font-weight:500;color:#697386}.event-tab.active,.division-tab.active{border-color:#9e1b32;background:#9e1b32;color:#fff;box-shadow:0 5px 15px rgba(158,27,50,.18)}.event-tab.active small{color:#ffe4e9}.round-chip.active{border-color:#dc3545;background:#fff4f5}.control-frame{width:100%;border:0;min-height:720px;background:transparent}select.form-select,select.form-select option{background-color:#fff!important;color:#111827!important;-webkit-text-fill-color:#111827!important;color-scheme:light}@media(max-width:767.98px){main.container{max-width:none;padding:10px}.control-frame{min-height:1100px}.event-check{min-height:52px}.event-tab{min-width:175px}.workspace .card-body{padding:12px}}</style></head><body><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="<?= $test?'../scoring-tests/select-mode.php':'../scoring/' ?>"><?= $test?'Scoring Tests':'BDC Scoring' ?></a><a class="btn btn-light btn-sm" href="../">⌂ Dashboard</a></div></nav><main class="container py-4"><?php if($test):?><div class="alert alert-warning fw-bold">TEST MODE · Projection data comes only from Scoring Tests.</div><?php endif;?><?php if($notice):?><div class="alert alert-success"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="mb-3"><div class="text-uppercase text-danger fw-bold small">Festival Presentation</div><h1 class="h2 mb-1"><?=e($title)?></h1><p class="text-muted">Run one event or create one shared projection for multiple Jack & Jill events.</p></div>
<div class="card festival shadow-sm mb-4"><div class="card-body"><div class="d-flex flex-wrap justify-content-between gap-2 align-items-center"><div><h2 class="h5 mb-1">Multi-Event Festival Projection</h2><div class="small text-muted">One permanent projector link. Every event or round switch automatically returns the audience to Holding Screen.</div></div><?php if($saved):?><select class="form-select w-auto" onchange="if(this.value)location.href='?festival_session='+this.value"><option value="">Open saved festival…</option><?php foreach($saved as $item):?><option value="<?=(int)$item['id']?>" <?= $sessionId===(int)$item['id']?'selected':'' ?>><?=e((string)$item['group_name'])?> · <?=(int)$item['event_count']?> events</option><?php endforeach;?></select><?php endif;?></div><form method="post" action="festival-session.php" class="mt-3"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="data_mode" value="<?=$test?'test':'real'?>"><div class="row g-2 mb-2"><div class="col-md-5"><input name="group_name" class="form-control" placeholder="Festival name, e.g. Asia J&J Festival" value="<?=e((string)($festival['group_name']??''))?>"></div><div class="col-md-7 d-flex align-items-center small text-muted">Select at least two events. Creating again safely regenerates this festival projector link.</div></div><div class="row g-2"><?php foreach($events as $event):?><div class="col-md-6"><label class="event-check d-flex gap-2 align-items-center"><input class="form-check-input mt-0" type="checkbox" name="event_ids[]" value="<?=(int)$event['id']?>" <?= $festival&&in_array((int)$event['id'],$allowed,true)?'checked':'' ?>><span><strong><?=e((string)$event['name'])?></strong><?php if($event['event_date']):?><small class="d-block text-muted"><?=e((string)$event['event_date'])?></small><?php endif;?></span></label></div><?php endforeach;?></div><button class="btn btn-danger mt-3">Create / Regenerate Festival Projection</button></form></div></div>
<?php if($festival):?><div class="alert alert-dark d-flex flex-wrap justify-content-between align-items-center gap-2"><span><strong><?=e((string)$festival['group_name'])?></strong> · <?=count($members)?> selected events</span><a class="btn btn-sm btn-outline-light" href="<?=$test?'test-index.php':'index.php'?>">Exit festival mode</a></div><?php endif;?>
<?php if($festival):?><div class="row g-3 mb-4"><div class="col-lg-5"><div class="card workspace shadow-sm h-100"><div class="card-body"><h2 class="h5">Custom Holding Screen</h2><p class="small text-muted">Upload your festival artwork. It fills the projector while content is protected or between event selections.</p><?php if(!empty($festival['holding_background_url'])):?><img src="<?=e((string)$festival['holding_background_url'])?>" alt="Current Holding Screen" class="img-fluid rounded border mb-3" style="aspect-ratio:16/9;object-fit:cover"><?php endif;?><form method="post" action="holding-background.php" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="session_id" value="<?=$sessionId?>"><input type="hidden" name="data_mode" value="<?=$test?'test':'real'?>"><input class="form-control mb-2" type="file" name="background" accept="image/jpeg,image/png,image/webp" required><div class="small text-muted mb-2">JPG, PNG or WebP · minimum 1280 × 720 · maximum 12 MB.</div><button class="btn btn-dark" name="action" value="upload">Upload &amp; Show Holding Screen</button><?php if(!empty($festival['holding_background_url'])):?><button class="btn btn-outline-danger" name="action" value="remove" formnovalidate>Remove</button><?php endif;?></form></div></div></div><div class="col-lg-7"><form class="card workspace shadow-sm h-100" method="post" action="festival-playlist.php"><div class="card-body"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="session_id" value="<?=$sessionId?>"><input type="hidden" name="data_mode" value="<?=$test?'test':'real'?>"><div class="d-flex justify-content-between gap-2"><div><h2 class="h5 mb-1">Multi-Event Results Loop</h2><p class="small text-muted">Choose podium and Final score slides from any selected festival event. Slides play in the order below.</p></div><?php if(!empty($festival['playlist_enabled'])):?><span class="badge text-bg-success align-self-start">LOOPING</span><?php endif;?></div><?php if(!$festivalFinals):?><div class="alert alert-warning mb-0">No Final rounds are available in the selected events.</div><?php else:?><div class="vstack gap-2 mb-3" style="max-height:310px;overflow:auto"><?php foreach($festivalFinals as $final):?><div class="border rounded p-2"><div class="fw-bold"><?=e((string)$final['event_name'])?></div><div class="small text-muted mb-1"><?=e(ucwords(str_replace('_',' ',(string)$final['division'])))?> Final · <?=e(ucwords(str_replace('_',' ',(string)$final['status'])))?></div><div class="d-flex flex-wrap gap-3"><label><input class="form-check-input" type="checkbox" name="slides[]" value="<?=(int)$final['id']?>:winners" <?=in_array($final['id'].':winners',$playlistSelected,true)?'checked':''?>> Winner Podium</label><label><input class="form-check-input" type="checkbox" name="slides[]" value="<?=(int)$final['id']?>:final_results" <?=in_array($final['id'].':final_results',$playlistSelected,true)?'checked':''?>> Final Score Matrix</label></div></div><?php endforeach;?></div><div class="d-flex flex-wrap gap-2 align-items-end"><div><label class="form-label mb-1">Slide duration</label><select class="form-select" name="delay"><?php foreach([5,10,15,20,30,45,60] as $delay):?><option value="<?=$delay?>" <?=(int)($festival['loop_delay_seconds']??15)===$delay?'selected':''?>><?=$delay?> seconds</option><?php endforeach;?></select></div><label class="form-check mb-2"><input class="form-check-input" type="checkbox" name="confirmation" value="1" required> Results are ready for public display</label><button class="btn btn-danger mb-1" name="action" value="start">Save &amp; Start Loop</button><?php if(!empty($festival['playlist_enabled'])):?><button class="btn btn-outline-dark mb-1" name="action" value="stop" formnovalidate>Stop &amp; Hold</button><?php endif;?></div><?php endif;?></div></form></div></div><?php endif;?>
<div class="card workspace shadow-sm mb-4"><div class="card-body"><?php if($festival):?><div class="small text-muted fw-bold mb-2">SWITCH EVENT — AUDIENCE RETURNS TO HOLDING SCREEN</div><div id="festivalEvents" class="festival-switcher"><?php foreach($members as $event):?><button type="button" class="event-tab" data-event="<?=(int)$event['id']?>"><?=e((string)$event['name'])?><small><?=e((string)($event['event_date']??''))?></small></button><?php endforeach;?></div><div id="divisionTabs" class="d-flex flex-wrap gap-2 mt-2"></div><div id="festivalRounds" class="d-flex flex-wrap gap-2 mt-2"></div><?php else:?><div class="row g-3"><div class="col-md-5"><label class="form-label fw-bold">Event</label><select id="event" class="form-select"><option value="">Select event...</option><?php foreach($events as $event):if(!in_array((int)$event['id'],$allowed,true))continue;?><option value="<?=(int)$event['id']?>"><?=e((string)$event['name'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label fw-bold">Category / Division</label><select id="division" class="form-select" disabled><option>Select category...</option></select></div><div class="col-md-3"><label class="form-label fw-bold">Round</label><select id="round" class="form-select" disabled><option>Select round...</option></select></div></div><?php endif;?></div></div><section id="selected" class="d-none"><div class="small text-muted">AVAILABLE ROUNDS</div><div id="roundsBar" class="d-flex flex-wrap gap-2 my-2"></div><iframe id="controlFrame" class="control-frame" title="<?=e($title)?> Control"></iframe></section></main><script>
const rounds=<?=json_encode($rounds,JSON_UNESCAPED_SLASHES)?>,controlBase=<?=json_encode($controlBase)?>,testMode=<?=$test?'true':'false'?>,festivalSession=<?=$festival?(int)$festival['id']:0?>,eventEl=document.querySelector('#event'),divisionEl=document.querySelector('#division'),roundEl=document.querySelector('#round'),selected=document.querySelector('#selected'),frame=document.querySelector('#controlFrame'),bar=document.querySelector('#roundsBar'),label=s=>String(s).replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());function reset(){selected.classList.add('d-none');frame.removeAttribute('src');bar.innerHTML=''}function openRound(id){const r=rounds.find(x=>Number(x.id)===Number(id));if(!r)return;document.querySelectorAll('[data-round]').forEach(b=>b.classList.toggle('active',Number(b.dataset.round)===Number(r.id)));const p=new URLSearchParams({embed:'1',selection:'1',round_id:r.id,data_mode:testMode?'test':'real',_:Date.now()});if(festivalSession)p.set('session_id',festivalSession);frame.src=controlBase+'?'+p;selected.classList.remove('d-none')}
if(festivalSession){const eventTabs=[...document.querySelectorAll('[data-event]')],divisionTabs=document.querySelector('#divisionTabs'),festivalRounds=document.querySelector('#festivalRounds');function chooseDivision(eventId,division){divisionTabs.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.division===division));const available=rounds.filter(r=>Number(r.event_id)===eventId&&r.division===division);festivalRounds.innerHTML=available.map(r=>`<button class="round-chip" type="button" data-round="${r.id}">${label(r.round_type)}</button>`).join('');festivalRounds.querySelectorAll('button').forEach(b=>b.onclick=()=>openRound(b.dataset.round))}function chooseEvent(eventId){reset();eventTabs.forEach(b=>b.classList.toggle('active',Number(b.dataset.event)===eventId));const divisions=[...new Set(rounds.filter(r=>Number(r.event_id)===eventId).map(r=>r.division))];divisionTabs.innerHTML=divisions.map(d=>`<button class="division-tab" type="button" data-division="${d}">${label(d)}</button>`).join('');divisionTabs.querySelectorAll('button').forEach(b=>b.onclick=()=>chooseDivision(eventId,b.dataset.division));festivalRounds.innerHTML='';if(divisions.length===1)chooseDivision(eventId,divisions[0])}eventTabs.forEach(b=>b.onclick=()=>chooseEvent(Number(b.dataset.event)));if(eventTabs.length)chooseEvent(Number(eventTabs[0].dataset.event))}else{eventEl.onchange=()=>{const id=Number(eventEl.value),v=[...new Set(rounds.filter(r=>Number(r.event_id)===id).map(r=>r.division))];divisionEl.innerHTML='<option value="">Select category...</option>'+v.map(x=>`<option value="${x}">${label(x)}</option>`).join('');divisionEl.disabled=!id;roundEl.disabled=true;reset()};divisionEl.onchange=()=>{const v=rounds.filter(r=>Number(r.event_id)===Number(eventEl.value)&&r.division===divisionEl.value);roundEl.innerHTML='<option value="">Select round...</option>'+v.map(x=>`<option value="${x.id}">${label(x.round_type)}</option>`).join('');roundEl.disabled=!divisionEl.value;bar.innerHTML=v.map(x=>`<button class="round-chip" type="button" data-round="${x.id}">${label(x.round_type)}</button>`).join('');bar.querySelectorAll('button').forEach(b=>b.onclick=()=>{roundEl.value=b.dataset.round;openRound(b.dataset.round)});selected.classList.add('d-none');frame.removeAttribute('src')};roundEl.onchange=()=>openRound(roundEl.value)}window.addEventListener('message',e=>{if(e.data?.type==='bdc-control-height')frame.style.height=Math.max(innerWidth<768?1000:620,Number(e.data.height)||720)+'px'});
</script></body></html>
